package io.github.b88878393.vaultsample.database;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Shows which PostgreSQL user the application is connected as.
 *
 * <p>{@code sessionUser} is the short-lived user generated by Vault's database secrets engine (for example
 * {@code v-approle-app-read-AbC123...}); {@code currentUser} is the shared {@code app_owner} group role that the
 * pool switches to with {@code SET ROLE} so that all generated users own and see the same tables.
 */
@RestController
@RequestMapping("/api/db")
public class DatabaseIdentityController {

    private final JdbcTemplate jdbcTemplate;

    public DatabaseIdentityController(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @GetMapping("/identity")
    public DatabaseIdentity identity() {
        return jdbcTemplate.queryForObject(
                "select session_user, current_user, current_database()",
                (rs, rowNum) -> new DatabaseIdentity(rs.getString(1), rs.getString(2), rs.getString(3)));
    }

    public record DatabaseIdentity(String sessionUser, String currentUser, String database) {
    }
}
